"use client"

import { useState } from "react"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"

// Mock data for states and districts
const stateDistrictData: Record<string, string[]> = {
  Gujarat: ["Ahmedabad", "Surat", "Rajkot", "Vadodara"],
  Maharashtra: ["Mumbai", "Pune", "Nagpur", "Nashik"],
  Rajasthan: ["Jaipur", "Udaipur", "Jodhpur", "Kota"],
}

export default function Home() {
  const [selectedState, setSelectedState] = useState("")
  const [districts, setDistricts] = useState<string[]>([])

  const handleStateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const state = e.target.value
    setSelectedState(state)
    setDistricts(stateDistrictData[state] || [])
  }

  return (
    <div>
      <Card className="w-full">
        <div className="flex">
          {/* Left Section - Form */}
          <div className="w-1/2 border-r p-2">
            <CardHeader className="pb-2">
              <CardTitle>Add/Edit the single record Here</CardTitle>
            </CardHeader>

            <CardContent>
              <form className="space-y-4">
                {/* First Name */}
                <FloatingInput id="firstName" label="First Name" type="text" />

                {/* Last Name */}
                <FloatingInput id="lastName" label="Last Name" type="text" />

                {/* Phone */}
                <FloatingInput id="phone" label="Phone" type="tel" />

                {/* Email */}
                <FloatingInput id="email" label="Email" type="email" />

                {/* Address */}
                <FloatingInput id="address" label="Address" type="text" />

                {/* Last Four Fields in 2x2 grid */}
                <div className="grid grid-cols-2 gap-4">
                  {/* State */}
                  <div className="relative w-full">
                    <select
                      id="state"
                      className="peer block w-full rounded-md border border-gray-300 px-3 pt-5 pb-2 text-sm
                                 focus:border-gray-500 focus:ring-0 focus:outline-none"
                      onChange={handleStateChange}
                      required
                    >
                      <option value="">Select State</option>
                      {Object.keys(stateDistrictData).map((state) => (
                        <option key={state} value={state}>
                          {state}
                        </option>
                      ))}
                    </select>
                    <label
                      htmlFor="state"
                      className="absolute left-3 -top-2 text-gray-500 text-xs px-1 bg-white"
                    >
                      State
                    </label>
                  </div>

                  {/* District */}
                  <div className="relative w-full">
                    <select
                      id="district"
                      className="peer block w-full rounded-md border border-gray-300 px-3 pt-5 pb-2 text-sm
                                 focus:border-gray-500 focus:ring-0 focus:outline-none"
                      required
                    >
                      <option value="">Select District</option>
                      {districts.map((d) => (
                        <option key={d} value={d}>
                          {d}
                        </option>
                      ))}
                    </select>
                    <label
                      htmlFor="district"
                      className="absolute left-3 -top-2 text-gray-500 text-xs px-1 bg-white"
                    >
                      District
                    </label>
                  </div>

                  {/* City */}
                  <FloatingInput id="city" label="City" type="text" />

                  {/* Zip */}
                  <FloatingInput id="zip" label="Zip" type="text" />
                </div>
              </form>
            </CardContent>
          </div>

          {/* Right Section */}
          <div className="w-1/2 p-2 border-b mx-6 flex items-center justify-center">
            <p className="text-muted-foreground">
              Right section content goes here (image, info, etc.)
            </p>
          </div>
        </div>
      </Card>
    </div>
  )
}

function FloatingInput({
  id,
  label,
  type,
}: {
  id: string
  label: string
  type: string
}) {
  return (
    <div className="relative w-full">
      <input
        type={type}
        id={id}
        placeholder=" "
        className="peer block w-full rounded-md border border-gray-300 px-3 pt-5 pb-2 text-sm 
                   focus:border-gray-500 focus:ring-0 focus:outline-none"
        required
      />
      <label
        htmlFor={id}
        className="absolute left-3 -top-2 text-gray-500 text-xs px-1 bg-white transition-all
          peer-placeholder-shown:top-4 peer-placeholder-shown:text-gray-400 peer-placeholder-shown:text-base
          peer-focus:-top-2 peer-focus:text-xs peer-focus:text-gray-600"
      >
        {label}
      </label>
    </div>
  )
}
